1809	fn initializers_from_population(
1810	    model: &sembla_ir::ValidatedModel,
1811	    population: &SyntheticPopulation,
1812	) -> Result<Vec<TableInit>, String> {
1813	    let population_boxes = model
1814	        .model()
1815	        .boxes
1816	        .iter()
1817	        .filter(|model_box| {
1818	            model_box.tables.iter().any(|table| {
1819	                table.name == "person"
1820	                    && table.attrs.iter().any(|attr| {
1821	                        attr.name == "health"
1822	                            && matches!(&attr.ty, AttrType::Enum { variants } if variants == &["S", "I", "R"])
1823	                    })
1824	                    && table.attrs.iter().any(|attr| {
1825	                        attr.name == "employer"
1826	                            && matches!(&attr.ty, AttrType::Ref { table } if table == "employer")
1827	                    })
1828	            }) && model_box.tables.iter().any(|table| table.name == "employer")
1829	        })
1830	        .collect::<Vec<_>>();
1831	    if population_boxes.is_empty() {
1832	        return Err(
1833	            "population file requires exactly one compatible person/employer schema, found 0"
1834	                .to_owned(),
1835	        );
1836	    }
1837	    let controller_boxes = model
1838	        .model()
1839	        .boxes
1840	        .iter()
1841	        .filter(|model_box| {
1842	            model_box.tables.iter().any(|table| {
1843	                table.name == "controller"
1844	                    && table.size_hint == 1
1845	                    && table.attrs.iter().any(|attr| attr.name == "mode")
1846	                    && table.attrs.iter().any(|attr| attr.name == "modifier")
1847	            })
1848	        })
1849	        .collect::<Vec<_>>();
1850	
1851	    let mut initial = Vec::new();
1852	    let mut initialized_population_boxes = Vec::new();
1853	    let mut initialized_controller_boxes = Vec::new();
1854	    if let [population_box] = population_boxes.as_slice() {
1855	        // Preserve the pre-PRD single-population behavior exactly.
1856	        let controller_box = match controller_boxes.as_slice() {
1857	            [] => None,
1858	            [model_box] => Some(*model_box),
1859	            _ => {
1860	                return Err(format!(
1861	                    "population file found {} compatible controller schemas",
1862	                    controller_boxes.len()
1863	                ));
1864	            }
1865	        };
1866	        initial.extend(match controller_box {
1867	            Some(controller) => population
1868	                .sir_policy_table_initializers_for_boxes(&population_box.name, &controller.name),
1869	            None => population.sir_table_initializers_for_box(&population_box.name),
1870	        });
1871	        initialized_population_boxes.push(population_box.name.as_str());
1872	        if let Some(controller) = controller_box {
1873	            initialized_controller_boxes.push(controller.name.as_str());
1874	        }
1875	    } else {
1876	        for (index, population_box) in population_boxes.iter().enumerate() {
1877	            let scope = parent_occurrence_path(&population_box.name);
1878	            if population_boxes[..index]
1879	                .iter()
1880	                .any(|other| parent_occurrence_path(&other.name) == scope)
1881	            {
1882	                return Err(format!(
1883	                    "population file found multiple compatible population schemas in occurrence scope '{scope}'"
1884	                ));
1885	            }
1886	            let matching_controllers = controller_boxes
1887	                .iter()
1888	                .filter(|controller| parent_occurrence_path(&controller.name) == scope)
1889	                .copied()
1890	                .collect::<Vec<_>>();
1891	            let controller = match matching_controllers.as_slice() {
1892	                [] if controller_boxes.is_empty() => None,
1893	                [controller] => Some(*controller),
1894	                _ => {
1895	                    return Err(format!(
1896	                        "population file found {} compatible controller schemas in occurrence scope '{scope}'",
1897	                        matching_controllers.len()
1898	                    ));
1899	                }
1900	            };
1901	            initial.extend(match controller {
1902	                Some(controller) => population.sir_policy_table_initializers_for_boxes(
1903	                    &population_box.name,
1904	                    &controller.name,
1905	                ),
1906	                None => population.sir_table_initializers_for_box(&population_box.name),
1907	            });
1908	            initialized_population_boxes.push(population_box.name.as_str());
1909	            if let Some(controller) = controller {
1910	                initialized_controller_boxes.push(controller.name.as_str());
1911	            }
1912	        }
1913	        if let Some(unmatched) = controller_boxes
1914	            .iter()
1915	            .find(|controller| !initialized_controller_boxes.contains(&controller.name.as_str()))
1916	        {
1917	            return Err(format!(
1918	                "population file found unmatched compatible controller schema '{}'",
1919	                unmatched.name
1920	            ));
1921	        }
1922	    }
1923	
1924	    for model_box in &model.model().boxes {
1925	        for table in &model_box.tables {
1926	            if (initialized_population_boxes.contains(&model_box.name.as_str())
1927	                && (table.name == "person" || table.name == "employer"))
1928	                || (initialized_controller_boxes.contains(&model_box.name.as_str())
1929	                    && table.name == "controller")
1930	            {
1931	                continue;
1932	            }
1933	            let row_count = usize::try_from(table.size_hint).map_err(|_| {
1934	                format!("{}.{} size_hint exceeds usize", model_box.name, table.name)
1935	            })?;
1936	            let columns = table
1937	                .attrs
1938	                .iter()
1939	                .map(|attr| {
1940	                    let data = match &attr.ty {
1941	                        AttrType::Real => ColumnData::Real(vec![0.0; row_count]),
1942	                        AttrType::Int => ColumnData::Int(vec![0; row_count]),
1943	                        AttrType::Enum { .. } => ColumnData::Enum(vec![0; row_count]),
1944	                        AttrType::Ref { .. } => ColumnData::Ref(vec![0; row_count]),
1945	                    };
 296	    std::fs::remove_dir_all(temp).unwrap();
 297	}
